```java
public class PushPromiseRead implements Http2StreamFrame {

    private Http2FrameStream stream;
    private final int promisedStreamId;
    private final Http2Headers headers;
    private final int padding;

    public PushPromiseRead(Http2FrameStream stream, int promisedStreamId, Http2Headers headers, int padding) {
        this.stream = stream;
        this.promisedStreamId = promisedStreamId;
        this.headers = headers;
        this.padding = padding;
    }

    @Override
    public Http2StreamFrame stream(Http2FrameStream stream) {
        this.stream = stream;
        return this;
    }

    @Override
    public Http2FrameStream stream() {
        return stream;
    }

    public int getPromisedStreamId() {
        return promisedStreamId;
    }

    public Http2Headers getHeaders() {
        return headers;
    }

    public int getPadding() {
        return padding;
    }

    @Override
    public String name() {
        return "PUSH_PROMISE_READ";
    }

    @Override
    public String toString() {
        return "PushPromiseRead{" +
                "streamId=" + stream.id() +
                ", promisedStreamId=" + promisedStreamId +
                ", headers=" + headers +
                ", padding=" + padding +
                '}';
    }
}

```

